using Microsoft.Extensions.Logging;
using VideoDownloader.Models;  namespace VideoDownloader.Services;  public sealed class MediaAnalysisResult {     public bool Success => Media is not null && string.IsNullOrWhiteSpace(ErrorMessage);     public string? ErrorMessage { get; init; }     public MediaInfo? Media { get; init; }     public bool IsAudioOnly { get; init; } }  public interface IMediaAnalysisService {     Task<MediaAnalysisResult> AnalyzeAsync(string url, bool includePlaylist, CancellationToken cancellationToken = default); }  public sealed class MediaAnalysisService : IMediaAnalysisService {     private readonly IYtDlpService _ytDlp;     private readonly ILogger<MediaAnalysisService> _logger;      public MediaAnalysisService(IYtDlpService ytDlp, ILogger<MediaAnalysisService> logger)     {         _ytDlp = ytDlp;         _logger = logger;     }      public async Task<MediaAnalysisResult> AnalyzeAsync(string url, bool includePlaylist, CancellationToken cancellationToken = default)     {         try         {             var result = await _ytDlp.GetMediaInfoAsync(url.Trim(), includePlaylist, cancellationToken).ConfigureAwait(false);             if (result.Success && result.Media is not null)             {                 return new MediaAnalysisResult                 {                     Media = result.Media,                     IsAudioOnly = result.Media.Formats.Count == 1 && result.Media.Formats.All(f => !f.HasVideo)                 };             }             return new MediaAnalysisResult { ErrorMessage = result.ErrorMessage ?? "Analysis failed." };         }         catch (OperationCanceledException)         {             return new MediaAnalysisResult { ErrorMessage = "Analysis was cancelled." };         }         catch (Exception ex)         {             _logger.LogError(ex, "Media analysis error for {Url}", url);             return new MediaAnalysisResult { ErrorMessage = "An unexpected error occurred during analysis." };         }     } }
